import{_ as t,o as c,c as o,a2 as d}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"方块、物品与 NBT 谓词及概率模型","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.11/util/predicates.md","filePath":"1.21.11/util/predicates.md"}'),a={name:"1.21.11/util/predicates.md"};function r(l,e,i,n,s,h){return c(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="方块、物品与-nbt-谓词及概率模型" tabindex="-1">方块、物品与 NBT 谓词及概率模型 <a class="header-anchor" href="#方块、物品与-nbt-谓词及概率模型" aria-label="Permalink to &quot;方块、物品与 NBT 谓词及概率模型&quot;">​</a></h1><p><code>dev.anvilcraft.lib.v2.util.predicate</code> 提供了一组带有完整 <code>Codec</code>、<code>StreamCodec</code> 与流式构建器的<strong>数据结构与状态匹配器</strong>，被 <code>module.recipe</code> 及外部配方/规则系统直接作为底层条件和概率输出载体使用。</p><h2 id="方块状态与方块实体匹配-blockstatepredicate" tabindex="-1">方块状态与方块实体匹配：<code>BlockStatePredicate</code> <a class="header-anchor" href="#方块状态与方块实体匹配-blockstatepredicate" aria-label="Permalink to &quot;方块状态与方块实体匹配：`BlockStatePredicate`&quot;">​</a></h2><p><code>BlockStatePredicate</code> 既能仅校验方块 ID/标签与 <code>BlockState</code> 属性（支持精确匹配和数值比较区间 <code>withMin</code> / <code>withMax</code> / <code>with(min, max)</code>），也能校验绑定的 <code>BlockEntity</code> NBT，同时支持离开主线程做纯离线 NBT 检查。</p><h3 id="匹配执行-api" tabindex="-1">匹配执行 API <a class="header-anchor" href="#匹配执行-api" aria-label="Permalink to &quot;匹配执行 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>test(LevelAccessor level, BlockState state, @Nullable BlockEntity entity)</code></td><td>完整在线校验：先比对方块集合与属性，若 <code>requiresBlockEntity()</code> 为真再对比实体 NBT</td></tr><tr><td><code>testWithoutEntity(BlockState state)</code></td><td>仅验证方块与方块属性是否满足</td></tr><tr><td><code>cannotMatch(BlockState state)</code></td><td>反向快速排除判定</td></tr><tr><td><code>testEntity(LevelAccessor level, BlockState state, @Nullable BlockEntity entity)</code></td><td>单独检查方块实体实时存储的 NBT</td></tr><tr><td><code>testOffThread(BlockState state, @Nullable CompoundTag entityNbt)</code> / <code>testEntityOffThread(...)</code></td><td>线程安全离线程版，适用于多线程配方索引或缓存预筛选</td></tr><tr><td><code>requiresBlockEntity()</code></td><td>当前谓词是否附加了 <code>CompoundTag</code> 实体校验条件</td></tr><tr><td><code>getStatesCache()</code> / <code>constructStatesForRender()</code></td><td>返回所有满足该谓词的离散 <code>BlockState</code> 列表（后者常用于在配方界面轮播渲染兼容方块）</td></tr><tr><td><code>getKey()</code></td><td>提取用于索引分类的规范资源键（如无则返 <code>BlockStatePredicate.EMPTY</code>）</td></tr></tbody></table><h3 id="blockstatepredicate-builder-构造方法" tabindex="-1"><code>BlockStatePredicate.Builder</code> 构造方法 <a class="header-anchor" href="#blockstatepredicate-builder-构造方法" aria-label="Permalink to &quot;`BlockStatePredicate.Builder` 构造方法&quot;">​</a></h3><ul><li>入口：<code>BlockStatePredicate.builder()</code></li><li>指定方块候选：<code>of(Block... blocks)</code>、<code>of(Supplier&lt;? extends Block&gt;... blocks)</code>、<code>of(Collection&lt;Block&gt;)</code>、<code>of(HolderGetter&lt;Block&gt; blocks, TagKey&lt;Block&gt; tag)</code></li><li>约束方块属性：<code>with(BlockState)</code>、<code>with(Property&lt;?&gt; prop, String val)</code>、<code>with(Property&lt;Integer&gt;, int)</code>、<code>with(Property&lt;Boolean&gt;, boolean)</code>、<code>with(Property&lt;T&gt;, T)</code>、区间 <code>with(Property&lt;T&gt;, Comparable, Comparable)</code> / <code>withMin(...)</code> / <code>withMax(...)</code></li><li>多组条件分支：<code>or()</code>（追加新的备选匹配分支）</li><li>实体 NBT：<code>nbt(CompoundTag tag)</code></li><li><code>build()</code> 生成最终不可变 <code>BlockStatePredicate</code>（内置 <code>CODEC</code> 与 <code>STREAM_CODEC</code>）。</li></ul><h2 id="物品与成分匹配-iitemstackpredicate、itempredicate-itemingredientpredicate" tabindex="-1">物品与成分匹配：<code>IItemStackPredicate</code>、<code>ItemPredicate</code> &amp; <code>ItemIngredientPredicate</code> <a class="header-anchor" href="#物品与成分匹配-iitemstackpredicate、itempredicate-itemingredientpredicate" aria-label="Permalink to &quot;物品与成分匹配：`IItemStackPredicate`、`ItemPredicate` &amp; `ItemIngredientPredicate`&quot;">​</a></h2><p>物品谓词基于 <code>HolderGetter&lt;Item&gt;</code> 绑定标签查询，并使用原版 <code>DataComponentMatchers</code> 统一表达精确组件匹配与部分组件谓词 (<code>DataComponentPredicate</code>) 匹配：</p><table tabindex="0"><thead><tr><th>类 / 接口</th><th>核心字段与构建 API</th></tr></thead><tbody><tr><td><code>IItemStackPredicate</code></td><td>通用物品匹配接口：<code>items()</code>、<code>components()</code>（返回 <code>DataComponentMatchers</code>）、<code>testCount(int)</code> 与 <code>testIgnoreCount(ItemStack)</code></td></tr><tr><td><code>ItemPredicate</code></td><td>使用 <code>MinMaxBounds.Ints</code> 约束堆叠数量；提供 <code>ItemPredicate.Builder.item().of(HolderGetter&lt;Item&gt;, TagKey&lt;Item&gt;) / of(...) .withCount(...) .withSubPredicate(DataComponentPredicate.Type&lt;T&gt;, T) .hasComponents(DataComponentMatchers) .build()</code></td></tr><tr><td><code>ItemIngredientPredicate</code></td><td>针对合成槽位式单定数量设计的匹配器（支持 <code>ItemIngredientPredicate.of(HolderGetter&lt;Item&gt;, TagKey&lt;Item&gt;)</code>、<code>withCount(int)</code>、<code>withSubPredicate(DataComponentPredicate.Type&lt;T&gt;, T)</code> 与 <code>hasComponents(DataComponentMatchers)</code>）；额外暴露 <code>getItems()</code>（<code>ItemStack[]</code>）方便渲染器展示示例材料</td></tr></tbody></table><p>二者均公开了 <code>CODEC</code> 与 <code>STREAM_CODEC</code> 常量（基于 <code>StreamCodecUtil.codec2Stream</code>）。</p><h2 id="轻量-nbt-匹配-nbtpredicate" tabindex="-1">轻量 NBT 匹配：<code>NbtPredicate</code> <a class="header-anchor" href="#轻量-nbt-匹配-nbtpredicate" aria-label="Permalink to &quot;轻量 NBT 匹配：`NbtPredicate`&quot;">​</a></h2><p><code>public record NbtPredicate(CompoundTag tag) implements Predicate&lt;Tag&gt;</code>（使用 <code>TagParser.LENIENT_CODEC</code> 支持宽松 SNBT 写法）：</p><ul><li><code>test(@Nullable Tag tag)</code>：递归比对超集（待检测 NBT 必须包含期望 <code>tag</code> 里的全部键与匹配值，允许包含额外未声明字段）；</li><li><code>test(ItemStack stack)</code> / <code>test(Entity entity)</code>：分别检查物品自定义 NBT/组件上下文与实体的完整保存数据；</li><li><code>NbtPredicate.getEntityTagToCompare(Entity entity)</code>：在 <code>ProblemReporter.ScopedCollector</code> + <code>TagValueOutput</code> 上下文中导出实体 NBT 并写入手持物 <code>SelectedItem</code>。</li></ul><h2 id="概率输出模型-chanceblockstate、weightedchanceblockstates-chanceitemstack" tabindex="-1">概率输出模型：<code>ChanceBlockState</code>、<code>WeightedChanceBlockStates</code> &amp; <code>ChanceItemStack</code> <a class="header-anchor" href="#概率输出模型-chanceblockstate、weightedchanceblockstates-chanceitemstack" aria-label="Permalink to &quot;概率输出模型：`ChanceBlockState`、`WeightedChanceBlockStates` &amp; `ChanceItemStack`&quot;">​</a></h2><p>用于描述配方输出或世界转变过程中“带权随机选一”或“附带产出概率/动态 <code>NumberProvider</code> 数量”的结果集（底层使用 <code>new LootParams(level, new ContextMap.Builder().create(new ContextKeySet.Builder().build()), Map.of(), 0)</code> 构造 <code>LootContext</code> 求值 <code>NumberProvider</code>）：</p><h3 id="_1-chanceitemstack-itemstack-stack-numberprovider-count" tabindex="-1">1. <code>ChanceItemStack(ItemStack stack, NumberProvider count)</code> <a class="header-anchor" href="#_1-chanceitemstack-itemstack-stack-numberprovider-count" aria-label="Permalink to &quot;1. `ChanceItemStack(ItemStack stack, NumberProvider count)`&quot;">​</a></h3><ul><li>构造工厂： <ul><li><code>ChanceItemStack.of(ItemLike item, int count / NumberProvider amount)</code></li><li><code>ChanceItemStack.of(ItemStack stack[, int count[, float chance]][, NumberProvider amount / float chance])</code></li></ul></li><li>运行结果与元数据：<code>getResult(ServerLevel level)</code>（对 <code>count</code> 结果限幅 <code>1..99</code> 并返回新副本 <code>ItemStack</code>）、<code>getItem()</code>、<code>getItemHolder()</code>、<code>getMaxCount()</code>、<code>getComponentsPatch()</code>。</li></ul><h3 id="_2-chanceblockstate-blockstate-state-compoundtag-nbt-numberprovider-chance" tabindex="-1">2. <code>ChanceBlockState(BlockState state, CompoundTag nbt, NumberProvider chance)</code> <a class="header-anchor" href="#_2-chanceblockstate-blockstate-state-compoundtag-nbt-numberprovider-chance" aria-label="Permalink to &quot;2. `ChanceBlockState(BlockState state, CompoundTag nbt, NumberProvider chance)`&quot;">​</a></h3><ul><li>构造重载：<code>ChanceBlockState(state, chance)</code>、<code>ChanceBlockState(state, float)</code>、<code>ChanceBlockState.of(Supplier&lt;? extends Block&gt;[, CompoundTag nbt])</code>。</li><li>运行结果：<code>@Nullable Map.Entry&lt;BlockState, CompoundTag&gt; getResult(ServerLevel level)</code>（随机抽取小于等于 <code>chance</code> 时返回命中状态与 NBT，否则返回 <code>null</code>）。</li></ul><h3 id="_3-weightedchanceblockstates-list-entry-states" tabindex="-1">3. <code>WeightedChanceBlockStates(List&lt;Entry&gt; states)</code> <a class="header-anchor" href="#_3-weightedchanceblockstates-list-entry-states" aria-label="Permalink to &quot;3. `WeightedChanceBlockStates(List&lt;Entry&gt; states)`&quot;">​</a></h3><p>按权重列表选出一个概率方块结果，通过 <code>WeightedChanceBlockStates.builder()</code> 构建：</p><ul><li><code>add(...)</code> 提供丰富参数组合重载，按需传入权重 <code>NumberProvider</code> / <code>float</code>、目标 <code>BlockState</code> / <code>Block</code> / <code>Supplier&lt;? extends Block&gt;</code>、可选实体 <code>CompoundTag</code> 以及产出几率 <code>NumberProvider</code> / <code>float</code>；</li><li><code>isEmpty()</code> 检查是否含任何条目，<code>build()</code> 完成构造，<code>getResult(ServerLevel)</code> 计算加权抽取并校验几率。</li></ul>',24)])])}const k=t(a,[["render",r]]);export{u as __pageData,k as default};
